.text 
main:
    jal display_background
    jal display_heart2
    jal display_heart
    jal display_person
    jal display_fire1
    jal display_fire2
    jal display_fire3
    jal game_loop

game_loop:
  
       jal play_one_note
    jal display_person


    # Read input (blocking)
    li $v0, 12
    syscall
    move $t2, $v0

    # Handle input
    li $t3, 'w'
    beq $t2, $t3, move_forward

    li $t3, 'e'
    beq $t2, $t3, move_left

    li $t3, ' '
    beq $t2, $t3, jump

skip_input:
    j game_loop

# ==== Move Forward ====
move_forward:
    jal clear_ground_person
    la $t0, personX
    lw $t1, 0($t0)
    addi $t1, $t1, 20   # move 20 pixels forward
    li $t2, 492         # boundary check (512 - character width 48)
    bgt $t1, $t2, no_move_forward
    sw $t1, 0($t0)

no_move_forward:
    jal display_person
    jal check_win
    jal check_collision   # <-- you forgot this!
    j game_loop

move_left:
    jal clear_ground_person
    la $t0, personX
    lw $t1, 0($t0)
    subi $t1, $t1, 20     # move 20 pixels left
    bltz $t1, no_move_left
    sw $t1, 0($t0)

no_move_left:
    jal display_person
    jal check_win
    jal check_collision
    j game_loop

jump:
    jal clear_ground_person

    # Jump up
    la $t0, personY
    lw $t1, 0($t0)
    subi $t1, $t1, 48
    sw $t1, 0($t0)
    jal display_person

    li $t9, 100
jump_delay1:
    subi $t9, $t9, 1
    bnez $t9, jump_delay1

    # Clear air before moving forward
    jal clear_air_person

    # Move forward 128
    la $t0, personX
    lw $t1, 0($t0)
    addi $t1, $t1, 128
    sw $t1, 0($t0)
    jal display_person

    li $t9, 100
jump_delay2:
    subi $t9, $t9, 1
    bnez $t9, jump_delay2

    # Descend to ground
    jal clear_air_person
    la $t0, personY
    lw $t1, 0($t0)
    addi $t1, $t1, 48
    sw $t1, 0($t0)
    jal display_person
    jal check_win
    jal check_collision
    j game_loop

check_collision:
    jal check_fire1
    jal check_fire2
    jal check_fire3
    jr $ra   # <-- don't jump to game_loop manually, just return normally


check_fire1:
    la $t0, personX
    lw $t1, 0($t0)

    li $t2, 112          # Rock1 X
    li $t3, 32           # Rock width

    # Check left foot
    move $t5, $t1
    blt $t5, $t2, check_right_foot1
    add $t6, $t2, $t3
    bgt $t5, $t6, check_right_foot1
    jal trigger_hit

check_right_foot1:
    li $t4, 72
    add $t5, $t1, $t4    # right foot = personX + 72
    blt $t5, $t2, check_middle1
    add $t6, $t2, $t3
    bgt $t5, $t6, check_middle1
    jal trigger_hit

check_middle1:
    li $t4, 36
    add $t5, $t1, $t4    # middle = personX + 36
    blt $t5, $t2, no_collision_fire1
    add $t6, $t2, $t3
    bgt $t5, $t6, no_collision_fire1
    jal trigger_hit

no_collision_fire1:
    jal check_fire2

# ==== Rock 2 Check ====
check_fire2:
    la $t0, personX
    lw $t1, 0($t0)

    li $t2, 280          # Rock2 X
    li $t3, 32

    # Check left foot
    move $t5, $t1
    blt $t5, $t2, check_right_foot2
    add $t6, $t2, $t3
    bgt $t5, $t6, check_right_foot2
    jal trigger_hit

check_right_foot2:
    li $t4, 72
    add $t5, $t1, $t4
    blt $t5, $t2, check_middle2
    add $t6, $t2, $t3
    bgt $t5, $t6, check_middle2
    jal trigger_hit

check_middle2:
    li $t4, 36
    add $t5, $t1, $t4
    blt $t5, $t2, no_collision_fire2
    add $t6, $t2, $t3
    bgt $t5, $t6, no_collision_fire2
    jal trigger_hit

no_collision_fire2:
    jal check_fire3

# ==== Rock 3 Check ====
check_fire3:
    la $t0, personX
    lw $t1, 0($t0)

    li $t2, 400          # Rock3 X
    li $t3, 32

    # Check left foot
    move $t5, $t1
    blt $t5, $t2, check_right_foot3
    add $t6, $t2, $t3
    bgt $t5, $t6, check_right_foot3
    jal trigger_hit

check_right_foot3:
    li $t4, 72
    add $t5, $t1, $t4
    blt $t5, $t2, check_middle3
    add $t6, $t2, $t3
    bgt $t5, $t6, check_middle3
    jal trigger_hit

check_middle3:
    li $t4, 36
    add $t5, $t1, $t4
    blt $t5, $t2, no_collision_fire3
    add $t6, $t2, $t3
    bgt $t5, $t6, no_collision_fire3
    jal trigger_hit

no_collision_fire3:
    jal game_loop



trigger_hit:
      jal display_dead_person
    # First "te"
    li $v0, 31
    li $a0, 80         # High short note
    li $a1, 100        # Duration 100 ms
    li $a2, 0
    li $a3, 127
    syscall

    # Small delay
    li $t9, 300
delay1:
    subi $t9, $t9, 1
    bnez $t9, delay1

    # Second "te"
    li $v0, 31
    li $a0, 80
    li $a1, 100
    li $a2, 0
    li $a3, 127
    syscall

    # Small delay
    li $t9, 300
delay2:
    subi $t9, $t9, 1
    bnez $t9, delay2

    # "ta"
    li $v0, 31
    li $a0, 70         # Lower pitch
    li $a1, 150        # Slightly longer
    li $a2, 0
    li $a3, 127
    syscall

    # Small delay
    li $t9, 400
delay3:
    subi $t9, $t9, 1
    bnez $t9, delay3

    # Final "taa"
    li $v0, 31
    li $a0, 60         # Deeper pitch
    li $a1, 300        # Long duration
    li $a2, 0
    li $a3, 127
    syscall
    la $t0, damage_counter
    lw $t1, 0($t0)

    li $t2, 0
    beq $t1, $t2, hide_heart1

    li $t2, 1
    beq $t1, $t2, hide_heart2

    # Should not reach here
    jr $ra


hide_heart1:

    # First "te"
    li $v0, 31
    li $a0, 80         # High short note
    li $a1, 100        # Duration 100 ms
    li $a2, 0
    li $a3, 127
    syscall

    # Small delay
    li $t9, 300
delay4:
    subi $t9, $t9, 1
    bnez $t9, delay4

    # Second "te"
    li $v0, 31
    li $a0, 80
    li $a1, 100
    li $a2, 0
    li $a3, 127
    syscall

    # Small delay
    li $t9, 300
delay5:
    subi $t9, $t9, 1
    bnez $t9, delay5

    # "ta"
    li $v0, 31
    li $a0, 70         # Lower pitch
    li $a1, 150        # Slightly longer
    li $a2, 0
    li $a3, 127
    syscall

    # Small delay
    li $t9, 400
delay6:
    subi $t9, $t9, 1
    bnez $t9, delay6

    # Final "taa"
    li $v0, 31
    li $a0, 60         # Deeper pitch
    li $a1, 300        # Long duration
    li $a2, 0
    li $a3, 127
    syscall
    li $t5, 0x10010000
    li $t0, 460        # Heart1 X
    li $t1, 10         # Heart1 Y
    li $t2, 512

    mul $t3, $t1, $t2
    add $t3, $t3, $t0
    mul $t3, $t3, 4
    add $t5, $t5, $t3

    la $t7, heart_cropped
    li $t4, 28

hide1_row:
    beqz $t4, done_hide1
    li $t6, 28

hide1_col:
    beqz $t6, next1_row
    lw $t8, 0($t7)
    sw $t8, 0($t5)
    addi $t7, $t7, 4
    addi $t5, $t5, 4
    subi $t6, $t6, 1
    j hide1_col

next1_row:
    subi $t4, $t4, 1
    addi $t5, $t5, 1936
    j hide1_row

done_hide1:
    la $t0, damage_counter
    li $t1, 1
    sw $t1, 0($t0)

    j game_loop


hide_heart2:
    li $t5, 0x10010000
    li $t0, 420        # Heart2 X
    li $t1, 10         # Heart2 Y
    li $t2, 512

    mul $t3, $t1, $t2
    add $t3, $t3, $t0
    mul $t3, $t3, 4
    add $t5, $t5, $t3

    la $t7, heart_cropped
    li $t4, 28

hide2_row:
    beqz $t4, done_hide2
    li $t6, 28

hide2_col:
    beqz $t6, next2_row
    lw $t8, 0($t7)
    sw $t8, 0($t5)
    addi $t7, $t7, 4
    addi $t5, $t5, 4
    subi $t6, $t6, 1
    j hide2_col

next2_row:
    subi $t4, $t4, 1
    addi $t5, $t5, 1936
    j hide2_row

done_hide2:
    la $t0, damage_counter
    li $t1, 2
    sw $t1, 0($t0)

    # NOW, after second heart is hidden, trigger game over
    jal Game_over
    li $v0, 10
    syscall



# ==== Display Background ====
display_background:
    la $t0, base_address
    lw $t0, 0($t0)         # Load framebuffer base address
    la $t1, image_background
    li $t2, 262144         # 512x512 = 262144 pixels

bg_loop:
    lw $t3, 0($t1)
    sw $t3, 0($t0)
    addi $t0, $t0, 4
    addi $t1, $t1, 4
    subi $t2, $t2, 1
    bnez $t2, bg_loop
    jr $ra

# ==== Display Heart ====
display_heart:
    li $t5, 0x10010000
    li $t0, 460           # Top-right X
    li $t1, 10            # Slightly down Y
    li $t2, 512

    mul $t3, $t1, $t2
    add $t3, $t3, $t0
    mul $t3, $t3, 4
    add $t5, $t5, $t3

    la $t7, heart
    li $t4, 28

heart_row:
    beqz $t4, end_heart
    li $t6, 28

heart_col:
    beqz $t6, next_heart_row
    lw $t8, 0($t7)
    sw $t8, 0($t5)
    addi $t7, $t7, 4
    addi $t5, $t5, 4
    subi $t6, $t6, 1
    j heart_col

next_heart_row:
    subi $t4, $t4, 1
    addi $t5, $t5, 1936    # (512x4)-(28x4)=1936
    j heart_row

end_heart:
    jr $ra
display_heart2:
    li $t5, 0x10010000
    li $t0, 420        # Top-right X
    li $t1, 10            # Slightly down Y
    li $t2, 512

    mul $t3, $t1, $t2
    add $t3, $t3, $t0
    mul $t3, $t3, 4
    add $t5, $t5, $t3

    la $t7, heart
    li $t4, 28

heart_row2:
    beqz $t4, end_heart2
    li $t6, 28

heart_col2:
    beqz $t6, next_heart_row2
    lw $t8, 0($t7)
    sw $t8, 0($t5)
    addi $t7, $t7, 4
    addi $t5, $t5, 4
    subi $t6, $t6, 1
    j heart_col2

next_heart_row2:
    subi $t4, $t4, 1
    addi $t5, $t5, 1936    # (512x4)-(28x4)=1936
    j heart_row2

end_heart2:
    jr $ra

# ==== Display Person ====
display_person:
    li $t5, 0x10010000
    la $t0, personX
    lw $t0, 0($t0)
    la $t1, personY
    lw $t1, 0($t1)
    li $t2, 512

    mul $t3, $t1, $t2
    add $t3, $t3, $t0
    mul $t3, $t3, 4
    add $t5, $t5, $t3

    la $t7, image_person
    li $t4, 96

person_row:
    beqz $t4, end_person
    li $t6, 96

person_col:
    beqz $t6, next_person_row
    lw $t8, 0($t7)
    sw $t8, 0($t5)
    addi $t7, $t7, 4
    addi $t5, $t5, 4
    subi $t6, $t6, 1
    j person_col

next_person_row:
    subi $t4, $t4, 1
    addi $t5, $t5, 1664    # (512x4)-(96x4)=1664
    j person_row

end_person:
    jr $ra

# ==== Display Rock ====
display_fire1:
    li $t5, 0x10010000
    li $t0, 112
    li $t1, 410
    li $t2, 512

    mul $t3, $t1, $t2
    add $t3, $t3, $t0
    mul $t3, $t3, 4
    add $t5, $t5, $t3

