display_fire3:
    li $t5, 0x10010000
    li $t0, 400
li $t1, 410
    li $t2, 512

    mul $t3, $t1, $t2
    add $t3, $t3, $t0
    mul $t3, $t3, 4
    add $t5, $t5, $t3

    la $t7, image_fire
    li $t4, 32

fire3_row:
    beqz $t4, end_fire3
    li $t6, 32

fire3_col:
    beqz $t6, next_fire3_row
    lw $t8, 0($t7)
    sw $t8, 0($t5)
    addi $t7, $t7, 4
    addi $t5, $t5, 4
    subi $t6, $t6, 1
    j fire3_col

next_fire3_row:
    subi $t4, $t4, 1
