# ==== Clear Ground Person ====
clear_ground_person:
    li $t5, 0x10010000
    la $t0, personX
    lw $t0, 0($t0)
    la $t1, personY
    lw $t1, 0($t1)
    li $t2, 512

    mul $t3, $t1, $t2
    add $t3, $t3, $t0
    mul $t3, $t3, 4
    add $t5, $t5, $t3

    la $t7, cropped_image
    li $t4, 96

clr_ground_row:
    beqz $t4, clr_ground_done
    li $t6, 96

clr_ground_col:
    beqz $t6, next_ground_row
    lw $t8, 0($t7)
    sw $t8, 0($t5)
    addi $t7, $t7, 4
    addi $t5, $t5, 4
    subi $t6, $t6, 1
    j clr_ground_col

next_ground_row:
    subi $t4, $t4, 1
    addi $t5, $t5, 1664
    j clr_ground_row

clr_ground_done:
    jr $ra

# ==== Clear Air Person ====
clear_air_person:
    li $t5, 0x10010000
    la $t0, personX
    lw $t0, 0($t0)
    la $t1, personY
    lw $t1, 0($t1)
    li $t2, 512

    mul $t3, $t1, $t2
    add $t3, $t3, $t0
    mul $t3, $t3, 4
    add $t5, $t5, $t3

    la $t7, cropped_image
    li $t4, 96

clr_air_row:
    beqz $t4, clr_air_done
    li $t6, 96

clr_air_col:
    beqz $t6, next_air_row
    lw $t8, 0($t7)
    sw $t8, 0($t5)
    addi $t7, $t7, 4
    addi $t5, $t5, 4
    subi $t6, $t6, 1
    j clr_air_col

next_air_row:
    subi $t4, $t4, 1
    addi $t5, $t5, 1664
    j clr_air_row

clr_air_done:
    jr $ra

Game_over:
    la $t0, base_address
    lw $t0, 0($t0)         # Load framebuffer base address
    la $t1, gameOver
    li $t2, 262144         # 512x512 = 262144 pixels

bg_loop2:
    lw $t3, 0($t1)
    sw $t3, 0($t0)
    add $t0, $t0, 4
    add $t1, $t1, 4
    subi $t2, $t2, 1
    bnez $t2, bg_loop2
check_win:
    la $t0, personX
    lw $t1, 0($t0)

    li $t2, 416        # 512 - 96

    bge $t1, $t2, win_game
    jr $ra

win_game:
    # Display win screen
    la $t0, base_address
    lw $t0, 0($t0)
    la $t1, winScreen    # <-- You need to have this image defined in .data
    li $t2, 262144       # 512x512

win_loop:
    lw $t3, 0($t1)
    sw $t3, 0($t0)
    addi $t0, $t0, 4
    addi $t1, $t1, 4
    subi $t2, $t2, 1
    bnez $t2, win_loop

    # ===== Victory Sound =====

    # First "ta" (happy)
    li $v0, 31
    li $a0, 85
    li $a1, 150
    li $a2, 0
    li $a3, 127
    syscall

    li $t9, 300
win_delay1:
    subi $t9, $t9, 1
    bnez $t9, win_delay1

    # Second "da"
    li $v0, 31
    li $a0, 90
    li $a1, 150
    li $a2, 0
    li $a3, 127
    syscall

    li $t9, 300
win_delay2:
    subi $t9, $t9, 1
    bnez $t9, win_delay2

    # Final "yaaay"
    li $v0, 31
    li $a0, 100
    li $a1, 400
    li $a2, 0
    li $a3, 127
    syscall

    # ===== End Game =====
    li $v0, 10
    syscall
play_one_note:
    # Load current note counter
    la $t0, music_counter
    lw $t1, 0($t0)

    # Play according to counter
    li $t2, 0
    beq $t1, $t2, music_C4

    li $t2, 1
    beq $t1, $t2, music_E4

    li $t2, 2
    beq $t1, $t2, music_G4

    li $t2, 3
    beq $t1, $t2, music_F4

    li $t2, 4
    beq $t1, $t2, music_D4

    # Reset if finished
    li $t1, 0
    sw $t1, 0($t0)
    jr $ra

music_C4:
    li $v0, 31
    li $a0, 60        # C4
    li $a1, 700
    li $a2, 0
    li $a3, 80
    syscall

    # increment counter
    la $t0, music_counter
    lw $t1, 0($t0)
    addi $t1, $t1, 1
    sw $t1, 0($t0)

    jr $ra

music_E4:
    li $v0, 31
    li $a0, 64        # E4
    li $a1, 700
    li $a2, 0
    li $a3, 80
    syscall

    la $t0, music_counter
    lw $t1, 0($t0)
    addi $t1, $t1, 1
    sw $t1, 0($t0)

    jr $ra

music_G4:
    li $v0, 31
    li $a0, 67        # G4
    li $a1, 800
    li $a2, 0
    li $a3, 85
    syscall

    la $t0, music_counter
    lw $t1, 0($t0)
    addi $t1, $t1, 1
    sw $t1, 0($t0)

    jr $ra

music_F4:
    li $v0, 31
    li $a0, 65        # F4
    li $a1, 800
    li $a2, 0
    li $a3, 75
    syscall

    la $t0, music_counter
    lw $t1, 0($t0)
    addi $t1, $t1, 1
    sw $t1, 0($t0)

    jr $ra

music_D4:
    li $v0, 31
    li $a0, 62        # D4
    li $a1, 800
    li $a2, 0
    li $a3, 75
    syscall

    la $t0, music_counter
    li $t1, 0
    sw $t1, 0($t0)

    jr $ra
display_dead_person:
    li $t5, 0x10010000      # Framebuffer base
    la $t0, personX
    lw $t0, 0($t0)          # Load personX
    la $t1, personY
    lw $t1, 0($t1)          # Load personY
    li $t2, 512             # Screen width in pixels

    mul $t3, $t1, $t2       # y * 512
    add $t3, $t3, $t0       # (y * 512) + x
    mul $t3, $t3, 4         # Multiply by 4 (word addressing)
    add $t5, $t5, $t3       # Final address to draw

    la $t7, dead_char       # Load the dead character image
    li $t4, 96              # 96 rows

dead_row:
    beqz $t4, end_dead
    li $t6, 96              # 96 columns

dead_col:
    beqz $t6, next_dead_row
    lw $t8, 0($t7)
    sw $t8, 0($t5)
    addi $t7, $t7, 4
    addi $t5, $t5, 4
    subi $t6, $t6, 1
    j dead_col

next_dead_row:
    subi $t4, $t4, 1
    addi $t5, $t5, 1664     # 512*4 - 96*4 = 1664 to jump to next row
    j dead_row

end_dead:
    jr $ra

 
